"""Shared utilities for RICE.

This module provides helper functions used across the RICE codebase:
- Trajectory collection and evaluation.
- Environment state save/load abstractions.
- Observation normalization and running statistics.
- Environment introspection (obs/action dims, Gym/Gymnasium compatibility).
- Random seeding.
"""

from typing import Any, Callable, Dict, List, Optional, Tuple, Union

import gym
import numpy as np
import torch


def set_seed(seed: int) -> None:
    """Set random seeds for reproducibility across numpy, torch, and gym."""
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def is_gymnasium(env: gym.Env) -> bool:
    """Return True if the environment follows the Gymnasium API (5-tuple step)."""
    # A simple heuristic: check the module name of the step return signature.
    try:
        import gymnasium as gymnasium_lib
        return isinstance(env, gymnasium_lib.Env)
    except Exception:
        return False


def step_env(
    env: gym.Env, action: np.ndarray
) -> Tuple[np.ndarray, float, bool, Dict[str, Any]]:
    """Step environment and normalize Gymnasium 5-tuple to 4-tuple output."""
    result = env.step(action)
    if len(result) == 5:
        obs, reward, terminated, truncated, info = result
        done = terminated or truncated
        info["terminated"] = terminated
        info["truncated"] = truncated
        return obs, float(reward), done, info
    else:
        return result


def reset_env(env: gym.Env, seed: Optional[int] = None) -> np.ndarray:
    """Reset environment, handling both Gym and Gymnasium APIs."""
    if seed is not None:
        try:
            result = env.reset(seed=seed)
        except TypeError:
            result = env.reset()
    else:
        result = env.reset()
    if isinstance(result, tuple):
        obs, info = result
        return obs
    return result


def get_obs_dim(env: gym.Env) -> int:
    """Infer observation dimension from a Gym/Gymnasium environment."""
    obs_space = env.observation_space
    if isinstance(obs_space, gym.spaces.Box):
        return int(np.prod(obs_space.shape))
    elif isinstance(obs_space, gym.spaces.Discrete):
        return int(obs_space.n)
    else:
        raise ValueError(f"Unsupported observation space: {obs_space}")


def get_action_dim(env: gym.Env) -> int:
    """Infer action dimension from a Gym/Gymnasium environment."""
    action_space = env.action_space
    if isinstance(action_space, gym.spaces.Box):
        return int(np.prod(action_space.shape))
    elif isinstance(action_space, gym.spaces.Discrete):
        return int(action_space.n)
    else:
        raise ValueError(f"Unsupported action space: {action_space}")


def is_continuous_action(env: gym.Env) -> bool:
    """Return True if the environment has a continuous action space."""
    return isinstance(env.action_space, gym.spaces.Box)


def sample_action(env: gym.Env) -> np.ndarray:
    """Sample a random action from the environment action space."""
    return env.action_space.sample()


class RunningMeanStd:
    """Online running mean and standard deviation tracker.

    Useful for normalizing observations or rewards incrementally.
    """

    def __init__(self, shape: Tuple[int, ...] = ()) -> None:
        self.mean = np.zeros(shape, dtype=np.float64)
        self.var = np.ones(shape, dtype=np.float64)
        self.count = 1e-4
        self.shape = shape

    def update(self, x: np.ndarray) -> None:
        """Update running statistics with a batch of samples."""
        x = np.asarray(x, dtype=np.float64)
        if x.shape == self.shape:
            x = x[np.newaxis, ...]
        batch_mean = np.mean(x, axis=0)
        batch_var = np.var(x, axis=0)
        batch_count = x.shape[0]
        self._update_from_moments(batch_mean, batch_var, batch_count)

    def _update_from_moments(
        self, batch_mean: np.ndarray, batch_var: np.ndarray, batch_count: int
    ) -> None:
        delta = batch_mean - self.mean
        tot_count = self.count + batch_count
        new_mean = self.mean + delta * batch_count / tot_count
        m_a = self.var * self.count
        m_b = batch_var * batch_count
        m2 = m_a + m_b + np.square(delta) * self.count * batch_count / tot_count
        new_var = m2 / tot_count
        self.mean = new_mean
        self.var = new_var
        self.count = tot_count

    @property
    def std(self) -> np.ndarray:
        return np.sqrt(self.var + 1e-8)


class Normalizer:
    """Normalize inputs using running mean and std.

    Optionally clips normalized values and supports fixed normalization.
    """

    def __init__(
        self,
        shape: Tuple[int, ...] = (),
        clip: float = 10.0,
        update_stats: bool = True,
    ) -> None:
        self.rms = RunningMeanStd(shape)
        self.clip = clip
        self.update_stats = update_stats

    def normalize(self, x: np.ndarray) -> np.ndarray:
        if self.update_stats:
            self.rms.update(x)
        return np.clip(
            (x - self.rms.mean) / self.rms.std,
            -self.clip,
            self.clip,
        )

    def normalize_torch(self, x: torch.Tensor) -> torch.Tensor:
        mean = torch.from_numpy(self.rms.mean).to(x.device).float()
        std = torch.from_numpy(self.rms.std).to(x.device).float()
        return torch.clamp((x - mean) / std, -self.clip, self.clip)


class EnvStateHelper:
    """Best-effort helper to save/load environment simulator state.

    Tries multiple strategies:
    1. env.save_state / env.load_state (used by some custom envs).
    2. env.sim.get_state / env.sim.set_state (MuJoCo).
    3. env.get_state / env.set_state (generic).
    4. env.unwrapped.get_state / env.unwrapped.set_state.
    """

    def __init__(self, env: gym.Env) -> None:
        self.env = env
        self._save_fn, self._load_fn = self._detect_methods()

    def _detect_methods(self) -> Tuple[Optional[Callable], Optional[Callable]]:
        env = self.env
        candidates = [env, getattr(env, "env", None), getattr(env, "unwrapped", None)]
        for obj in candidates:
            if obj is None:
                continue
            if hasattr(obj, "save_state") and hasattr(obj, "load_state"):
                return obj.save_state, obj.load_state
            if hasattr(obj, "get_state") and hasattr(obj, "set_state"):
                return obj.get_state, obj.set_state
            if hasattr(getattr(obj, "sim", None), "get_state") and hasattr(
                getattr(obj, "sim", None), "set_state"
            ):
                return obj.sim.get_state, obj.sim.set_state
        return None, None

    def is_supported(self) -> bool:
        return self._save_fn is not None and self._load_fn is not None

    def get_state(self) -> Any:
        if not self.is_supported():
            raise RuntimeError("Environment does not support state save/load.")
        return self._save_fn()

    def set_state(self, state: Any) -> None:
        if not self.is_supported():
            raise RuntimeError("Environment does not support state save/load.")
        self._load_fn(state)

    def reset_to_state(self, state: Any) -> np.ndarray:
        """Reset environment and restore simulator state."""
        obs = reset_env(self.env)
        self.set_state(state)
        # Recompute observation from restored state if possible.
        if hasattr(self.env, "_get_obs"):
            try:
                obs = self.env._get_obs()
            except Exception:
                pass
        elif hasattr(getattr(self.env, "unwrapped", None), "_get_obs"):
            try:
                obs = self.env.unwrapped._get_obs()
            except Exception:
                pass
        return obs


def collect_trajectory(
    env: gym.Env,
    policy: Any,
    max_steps: int = 1000,
    deterministic: bool = True,
    render: bool = False,
) -> Dict[str, Any]:
    """Collect a single trajectory using a policy.

    The policy can be a Stable-Baselines3 model or any callable that accepts
    an observation and returns an action (and optionally a dict).
    """
    obs = reset_env(env)
    observations, actions, rewards, dones, infos = [obs], [], [], [], []
    total_reward = 0.0
    done = False
    steps = 0

    while not done and steps < max_steps:
        if hasattr(policy, "predict"):
            action, _ = policy.predict(obs, deterministic=deterministic)
        else:
            result = policy(obs)
            action = result[0] if isinstance(result, tuple) else result

        action = np.asarray(action)
        obs, reward, done, info = step_env(env, action)
        if render:
            env.render()

        observations.append(obs)
        actions.append(action)
        rewards.append(reward)
        dones.append(done)
        infos.append(info)
        total_reward += reward
        steps += 1

    return {
        "observations": np.array(observations[:-1]),
        "next_observations": np.array(observations[1:]),
        "actions": np.array(actions),
        "rewards": np.array(rewards),
        "dones": np.array(dones),
        "infos": infos,
        "total_reward": total_reward,
        "length": steps,
    }


def collect_trajectories(
    env: gym.Env,
    policy: Any,
    n_trajectories: int = 10,
    max_steps: int = 1000,
    deterministic: bool = True,
) -> List[Dict[str, Any]]:
    """Collect multiple trajectories."""
    return [
        collect_trajectory(env, policy, max_steps, deterministic)
        for _ in range(n_trajectories)
    ]


def evaluate_policy(
    env: gym.Env,
    policy: Any,
    n_episodes: int = 10,
    max_steps: int = 1000,
    deterministic: bool = True,
) -> Tuple[float, float]:
    """Evaluate a policy and return mean and std of episode returns."""
    returns = []
    for _ in range(n_episodes):
        traj = collect_trajectory(
            env, policy, max_steps=max_steps, deterministic=deterministic
        )
        returns.append(traj["total_reward"])
    return float(np.mean(returns)), float(np.std(returns))


def randomize_actions_at_indices(
    env: gym.Env,
    policy: Any,
    initial_state: Any,
    indices: List[int],
    max_steps: int = 1000,
) -> float:
    """Roll out from a state, replacing actions at selected indices with random actions.

    Returns the total reward of the perturbed trajectory.
    """
    helper = EnvStateHelper(env)
    obs = helper.reset_to_state(initial_state)
    total_reward = 0.0
    done = False
    steps = 0

    while not done and steps < max_steps:
        if steps in indices:
            action = sample_action(env)
        else:
            if hasattr(policy, "predict"):
                action, _ = policy.predict(obs, deterministic=True)
            else:
                result = policy(obs)
                action = result[0] if isinstance(result, tuple) else result
            action = np.asarray(action)

        obs, reward, done, _ = step_env(env, action)
        total_reward += reward
        steps += 1

    return total_reward


def get_env_state(env: gym.Env) -> Any:
    """Convenience wrapper to get simulator state via EnvStateHelper."""
    return EnvStateHelper(env).get_state()


def set_env_state(env: gym.Env, state: Any) -> None:
    """Convenience wrapper to set simulator state via EnvStateHelper."""
    EnvStateHelper(env).set_state(state)


def reset_to_state(env: gym.Env, state: Any) -> np.ndarray:
    """Convenience wrapper to reset environment to a saved simulator state."""
    return EnvStateHelper(env).reset_to_state(state)


def explained_variance(y_pred: np.ndarray, y_true: np.ndarray) -> float:
    """Compute explained variance, commonly used to diagnose value function fit."""
    var_y = np.var(y_true)
    return float(np.nan_to_num(1 - np.var(y_true - y_pred) / (var_y + 1e-8)))


def discount_cumsum(rewards: np.ndarray, gamma: float) -> np.ndarray:
    """Compute discounted cumulative sums of rewards (returns)."""
    returns = np.zeros_like(rewards, dtype=np.float64)
    running = 0.0
    for t in reversed(range(len(rewards))):
        running = rewards[t] + gamma * running
        returns[t] = running
    return returns


if __name__ == "__main__":
    # Simple sanity check with a Gym environment.
    env = gym.make("CartPole-v1")
    obs_dim = get_obs_dim(env)
    action_dim = get_action_dim(env)
    print(f"CartPle obs_dim={obs_dim}, action_dim={action_dim}")

    class RandomPolicy:
        def __init__(self, env):
            self.env = env

        def predict(self, obs, deterministic=False):
            return self.env.action_space.sample(), None

    mean_return, std_return = evaluate_policy(env, RandomPolicy(env), n_episodes=5)
    print(f"Random policy return: {mean_return:.2f} +/- {std_return:.2f}")
    env.close()

