"""General utility helpers for the RICE reproduction.

This module collects small, reusable pieces of functionality that are used
across mask training, refining, explanation generation, and experiments:

* Reproducibility helpers (seed setting, device selection)
* Gym observation / action helpers
* Trajectory collection from a policy
* Simulator state save / load abstraction
* Policy evaluation
* Running mean / std normalization
"""

from __future__ import annotations

import os
import random
import warnings
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

import gym
import numpy as np
import torch
import torch.nn as nn


def set_seed(seed: int) -> None:
    """Set random seeds for reproducibility across numpy, torch, gym, and python."""
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)
    os.environ.setdefault("PYTHONHASHSEED", str(seed))


def get_device(device: Union[str, torch.device] = "auto") -> torch.device:
    """Resolve a device string to a torch.device."""
    if isinstance(device, torch.device):
        return device
    if device == "auto":
        return torch.device("cuda" if torch.cuda.is_available() else "cpu")
    return torch.device(device)


def flatten_obs(obs: np.ndarray) -> np.ndarray:
    """Flatten a Box observation to a 1-D float32 vector."""
    return np.asarray(obs, dtype=np.float32).reshape(-1)


def random_action(action_space: gym.Space) -> np.ndarray:
    """Sample a random action from a Gym action space."""
    action = action_space.sample()
    if isinstance(action_space, gym.spaces.Box):
        return np.asarray(action, dtype=np.float32).reshape(action_space.shape)
    return action


def get_obs_dim(observation_space: gym.Space) -> int:
    """Return the flattened dimension of a Box observation space."""
    if isinstance(observation_space, gym.spaces.Box):
        return int(np.prod(observation_space.shape))
    raise NotImplementedError(f"Unsupported observation space: {observation_space}")


def get_action_dim(action_space: gym.Space) -> int:
    """Return the dimension of a Box action space or number of discrete actions."""
    if isinstance(action_space, gym.spaces.Box):
        return int(np.prod(action_space.shape))
    if isinstance(action_space, gym.spaces.Discrete):
        return int(action_space.n)
    raise NotImplementedError(f"Unsupported action space: {action_space}")


class RunningMeanStd:
    """Online running mean and standard deviation estimator.

    This is a generic implementation that can be used for observation or
    reward normalization. It is kept separate from the RND-specific running
    statistics in ``rice.rnd`` so that it can be reused elsewhere.
    """

    def __init__(self, shape: Tuple[int, ...] = ()) -> None:
        self.mean = np.zeros(shape, dtype=np.float64)
        self.var = np.ones(shape, dtype=np.float64)
        self.count = 1e-4

    def update(self, x: np.ndarray) -> None:
        """Update running statistics with a batch of samples."""
        batch_mean = np.mean(x, axis=0)
        batch_var = np.var(x, axis=0)
        batch_count = x.shape[0]
        self.update_from_moments(batch_mean, batch_var, batch_count)

    def update_from_moments(
        self, batch_mean: np.ndarray, batch_var: np.ndarray, batch_count: int
    ) -> None:
        delta = batch_mean - self.mean
        tot_count = self.count + batch_count
        new_mean = self.mean + delta * batch_count / tot_count
        m_a = self.var * self.count
        m_b = batch_var * batch_count
        m2 = m_a + m_b + np.square(delta) * self.count * batch_count / tot_count
        new_var = m2 / tot_count
        self.mean = new_mean
        self.var = new_var
        self.count = tot_count

    def normalize(
        self, x: np.ndarray, epsilon: float = 1e-8
    ) -> np.ndarray:
        """Return a normalized copy of ``x`` using current statistics."""
        return (x - self.mean) / np.sqrt(self.var + epsilon)


class TrajectoryCollector:
    """Collect complete trajectories from a policy in a Gym environment.

    The collector handles both classic ``(obs, reward, done, info)`` and
    Gymnasium ``(obs, reward, terminated, truncated, info)`` step signatures.
    """

    def __init__(
        self,
        env: gym.Env,
        policy: Callable[[np.ndarray], np.ndarray],
        deterministic: bool = False,
        max_steps: Optional[int] = None,
    ) -> None:
        self.env = env
        self.policy = policy
        self.deterministic = deterministic
        self.max_steps = max_steps

    def collect(
        self, n_trajectories: int = 1, reset_kwargs: Optional[Dict[str, Any]] = None
    ) -> List[Dict[str, Any]]:
        """Collect ``n_trajectories`` complete trajectories.

        Returns
        -------
        trajectories : list of dict
            Each dict contains ``observations``, ``actions``, ``rewards``,
            ``dones``, ``infos``, ``total_reward``, and ``length``.
        """
        trajectories: List[Dict[str, Any]] = []
        reset_kwargs = reset_kwargs or {}
        for _ in range(n_trajectories):
            obs = self.env.reset(**reset_kwargs)
            obs_list: List[np.ndarray] = []
            action_list: List[np.ndarray] = []
            reward_list: List[float] = []
            done_list: List[bool] = []
            info_list: List[Dict[str, Any]] = []
            total_reward = 0.0
            length = 0

            while True:
                obs_arr = np.asarray(obs, dtype=np.float32)
                action = self.policy(obs_arr)
                obs_list.append(obs_arr)
                action_list.append(np.asarray(action))

                step_result = self.env.step(action)
                if len(step_result) == 5:
                    obs, reward, terminated, truncated, info = step_result
                    done = terminated or truncated
                else:
                    obs, reward, done, info = step_result

                reward_list.append(float(reward))
                done_list.append(bool(done))
                info_list.append(info)
                total_reward += float(reward)
                length += 1

                if done or (self.max_steps is not None and length >= self.max_steps):
                    break

            trajectories.append(
                {
                    "observations": np.stack(obs_list),
                    "actions": np.stack(action_list),
                    "rewards": np.array(reward_list, dtype=np.float32),
                    "dones": np.array(done_list, dtype=np.bool_),
                    "infos": info_list,
                    "total_reward": total_reward,
                    "length": length,
                }
            )
        return trajectories

    def collect_one(
        self, reset_kwargs: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        """Collect a single trajectory."""
        trajectories = self.collect(n_trajectories=1, reset_kwargs=reset_kwargs)
        return trajectories[0]


def get_env_state(env: gym.Env) -> Any:
    """Extract a restorable simulator state from a wrapped or raw environment.

    This function tries environment-specific helpers first (e.g. MuJoCo) and
    falls back to ``env.unwrapped`` state attributes when available.
    """
    # Try explicit wrapper methods first.
    if hasattr(env, "get_state") and callable(getattr(env, "get_state")):
        return env.get_state()

    # MuJoCo-specific fallback.
    unwrapped = getattr(env, "unwrapped", env)
    if hasattr(unwrapped, "sim") and hasattr(unwrapped.sim, "get_state"):
        return {
            "type": "mujoco",
            "state": unwrapped.sim.get_state(),
            "qpos": unwrapped.sim.data.qpos.copy(),
            "qvel": unwrapped.sim.data.qvel.copy(),
        }

    # Generic fallback: save the full unwrapped env state if available.
    if hasattr(unwrapped, "__getstate__"):
        return {"type": "pickle", "state": unwrapped.__getstate__()}

    raise NotImplementedError(
        "Environment does not expose a get_state method or a known simulator state."
    )


def set_env_state(env: gym.Env, state: Any) -> np.ndarray:
    """Restore a simulator state and return the corresponding observation.

    The function tries wrapper methods first, then environment-specific
    fallbacks, and finally raises an error if no mechanism is available.
    """
    if hasattr(env, "set_state") and callable(getattr(env, "set_state")):
        return env.set_state(state)

    unwrapped = getattr(env, "unwrapped", env)
    if isinstance(state, dict) and state.get("type") == "mujoco":
        unwrapped.sim.set_state(state["state"])
        unwrapped.sim.forward()
        return unwrapped.get_obs()

    if isinstance(state, dict) and state.get("type") == "pickle":
        if hasattr(unwrapped, "__setstate__"):
            unwrapped.__setstate__(state["state"])
            return unwrapped.get_obs()

    raise NotImplementedError(
        "Environment does not expose a set_state method or a known simulator state."
    )


def evaluate_policy(
    env: gym.Env,
    policy: Callable[[np.ndarray], np.ndarray],
    n_eval_episodes: int = 10,
    deterministic: bool = True,
    max_steps: Optional[int] = None,
    seed: Optional[int] = None,
) -> Tuple[float, float]:
    """Evaluate a policy and return mean and standard deviation of returns."""
    if seed is not None:
        set_seed(seed)

    collector = TrajectoryCollector(
        env=env,
        policy=policy,
        deterministic=deterministic,
        max_steps=max_steps,
    )
    trajectories = collector.collect(n_trajectories=n_eval_episodes)
    returns = np.array([traj["total_reward"] for traj in trajectories], dtype=np.float32)
    return float(np.mean(returns)), float(np.std(returns))


def init_orthogonal(module: nn.Module) -> None:
    """Initialize a linear layer with orthogonal weights and zero bias."""
    if isinstance(module, nn.Linear):
        nn.init.orthogonal_(module.weight, gain=np.sqrt(2))
        if module.bias is not None:
            nn.init.constant_(module.bias, 0.0)


def explained_variance(y_pred: np.ndarray, y_true: np.ndarray) -> float:
    """Compute explained variance, a common value-function diagnostic."""
    var_y = np.var(y_true)
    return float(np.var(y_true - y_pred) / (var_y + 1e-8))


def safe_mean(arr: Union[np.ndarray, List[float]]) -> float:
    """Return the mean of an array, or 0.0 for empty input."""
    if len(arr) == 0:
        return 0.0
    return float(np.mean(arr))


def discount_cumsum(rewards: np.ndarray, gamma: float) -> np.ndarray:
    """Compute discounted cumulative sums of a 1-D reward vector."""
    ret = np.zeros_like(rewards, dtype=np.float32)
    running = 0.0
    for t in reversed(range(len(rewards))):
        running = rewards[t] + gamma * running
        ret[t] = running
    return ret

