"""MuJoCo environment wrappers for RICE.

Provides dense-reward Gym wrappers and sparse-reward variants used in the paper,
along with state save/load support via ``env.sim.get_state`` / ``env.sim.set_state``.
"""

from typing import Any, Dict, Optional, Tuple, Union

import gym
import numpy as np


class MujocoStateWrapper(gym.Wrapper):
    """Base wrapper that exposes ``get_state`` / ``set_state`` for MuJoCo envs.

    The wrapped environment must be a ``gym.envs.mujoco`` environment with a
    ``sim`` attribute.  The state is returned as a copy of ``sim.get_state()``
    so that it can be restored later with ``sim.set_state()``.
    """

    def __init__(self, env: gym.Env):
        super().__init__(env)
        if not hasattr(self.env, "sim"):
            raise ValueError(
                "MujocoStateWrapper requires the wrapped env to have a 'sim' attribute"
            )

    def get_state(self) -> np.ndarray:
        """Return a snapshot of the current simulator state."""
        return self.env.sim.get_state()

    def set_state(self, state: np.ndarray) -> None:
        """Restore the simulator to ``state`` and synchronize the wrapped env."""
        self.env.sim.set_state(state)
        self.env.sim.forward()

    def reset(self, **kwargs: Any) -> np.ndarray:
        # Gym 0.21 reset returns only obs; Gymnasium returns (obs, info).
        result = self.env.reset(**kwargs)
        if isinstance(result, tuple):
            return result
        return result, {}

    def step(self, action: np.ndarray) -> Tuple[np.ndarray, float, bool, bool, Dict[str, Any]]:
        result = self.env.step(action)
        # Normalize to the 5-tuple Gymnasium API internally.
        if len(result) == 4:
            obs, reward, done, info = result
            terminated = bool(done)
            truncated = False
        elif len(result) == 5:
            obs, reward, terminated, truncated, info = result
        else:
            raise RuntimeError(f"Unexpected step return length: {len(result)}")
        return obs, float(reward), bool(terminated), bool(truncated), info


class SparseRewardWrapper(MujocoStateWrapper):
    """Sparse reward wrapper for forward-locomotion MuJoCo tasks.

    Reward is the forward velocity (x-position delta) only when the agent's
    x-position exceeds ``threshold``; otherwise the reward is zero.
    """

    def __init__(self, env: gym.Env, threshold: float = 0.6):
        super().__init__(env)
        self.threshold = threshold
        self._last_x: Optional[float] = None

    def reset(self, **kwargs: Any) -> Tuple[np.ndarray, Dict[str, Any]]:
        result = super().reset(**kwargs)
        obs = result[0] if isinstance(result, tuple) else result
        self._last_x = self.env.sim.data.qpos[0]
        return result

    def step(self, action: np.ndarray) -> Tuple[np.ndarray, float, bool, bool, Dict[str, Any]]:
        obs, _, terminated, truncated, info = super().step(action)
        x = self.env.sim.data.qpos[0]
        if self._last_x is None:
            self._last_x = x
        dense_reward = x - self._last_x  # forward velocity component
        self._last_x = x
        reward = dense_reward if x > self.threshold else 0.0
        info["dense_reward"] = dense_reward
        info["x_position"] = x
        return obs, reward, terminated, truncated, info


def make_mujoco_env(env_id: str, sparse: bool = False, **kwargs: Any) -> gym.Env:
    """Create a MuJoCo environment wrapped for RICE.

    Args:
        env_id: Registered Gym environment id, e.g. ``Hopper-v3``.
        sparse: If True, wrap with the sparse-reward variant (when available).
        **kwargs: Extra arguments forwarded to ``gym.make``.

    Returns:
        A wrapped ``gym.Env`` with ``get_state`` / ``set_state`` methods.
    """
    env = gym.make(env_id, **kwargs)

    # Sparse variants are only defined for forward-locomotion tasks.
    if sparse:
        thresholds = {
            "Hopper": 0.6,
            "Walker2d": 0.6,
            "HalfCheetah": 5.0,
        }
        for prefix, threshold in thresholds.items():
            if prefix in env_id:
                env = SparseRewardWrapper(env, threshold=threshold)
                break
        else:
            raise ValueError(f"No sparse reward variant defined for {env_id}")
    else:
        env = MujocoStateWrapper(env)

    return env


# Convenience constructors used by experiment scripts and configs.

def make_hopper(sparse: bool = False, **kwargs: Any) -> gym.Env:
    return make_mujoco_env("Hopper-v3", sparse=sparse, **kwargs)


def make_walker2d(sparse: bool = False, **kwargs: Any) -> gym.Env:
    return make_mujoco_env("Walker2d-v3", sparse=sparse, **kwargs)


def make_halfcheetah(sparse: bool = False, **kwargs: Any) -> gym.Env:
    return make_mujoco_env("HalfCheetah-v3", sparse=sparse, **kwargs)


def make_reacher(**kwargs: Any) -> gym.Env:
    return make_mujoco_env("Reacher-v2", sparse=False, **kwargs)

"""Shared utilities for RICE.

This module provides helper functions and classes used across the RICE codebase:
- Global seeding
- Trajectory collection from a fixed or trainable policy
- Environment state save/load helpers (with fallbacks for sim-based and replay-based resets)
- Running mean / standard deviation normalization
- Stable-Baselines3 policy loading helpers
"""

import os
import random
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

import gym
import numpy as np
import torch
import torch.nn as nn


def set_seed(seed: Optional[int], env: Optional[gym.Env] = None) -> None:
    """Set random seeds for reproducibility.

    Args:
        seed: Integer seed. If None, no seeding is performed.
        env: Optional environment whose seed should also be set.
    """
    if seed is None:
        return
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)
    if env is not None:
        try:
            env.seed(seed)
        except Exception:
            # Newer gymnasium API
            try:
                env.reset(seed=seed)
            except Exception:
                pass


def get_obs_shape(observation_space: gym.Space) -> Tuple[int, ...]:
    """Return the shape of observations produced by a Gym observation space."""
    if isinstance(observation_space, gym.spaces.Box):
        return observation_space.shape
    if isinstance(observation_space, gym.spaces.Discrete):
        return (1,)
    raise NotImplementedError(f"Unsupported observation space: {observation_space}")


def get_action_dim(action_space: gym.Space) -> int:
    """Return the dimensionality of a Gym action space."""
    if isinstance(action_space, gym.spaces.Box):
        return int(np.prod(action_space.shape))
    if isinstance(action_space, gym.spaces.Discrete):
        return int(action_space.n)
    if isinstance(action_space, gym.spaces.MultiDiscrete):
        return int(sum(action_space.nvec))
    raise NotImplementedError(f"Unsupported action space: {action_space}")


def normalize_obs(obs: np.ndarray, mean: np.ndarray, std: np.ndarray, eps: float = 1e-8) -> np.ndarray:
    """Normalize an observation using running statistics."""
    return (obs - mean) / (std + eps)


class RunningMeanStd:
    """Thread-unsafe running mean and standard deviation tracker.

    This is a generic version that can be used for observations or RND bonuses.
    """

    def __init__(self, shape: Tuple[int, ...] = ()) -> None:
        self.mean = np.zeros(shape, dtype=np.float64)
        self.var = np.ones(shape, dtype=np.float64)
        self.count = 1e-4

    def update(self, x: np.ndarray) -> None:
        """Update running statistics with a batch of samples."""
        batch_mean = np.mean(x, axis=0)
        batch_var = np.var(x, axis=0)
        batch_count = x.shape[0]
        self._update_from_moments(batch_mean, batch_var, batch_count)

    def _update_from_moments(self, batch_mean: np.ndarray, batch_var: np.ndarray, batch_count: int) -> None:
        delta = batch_mean - self.mean
        tot_count = self.count + batch_count
        new_mean = self.mean + delta * batch_count / tot_count
        m_a = self.var * self.count
        m_b = batch_var * batch_count
        m2 = m_a + m_b + np.square(delta) * self.count * batch_count / tot_count
        new_var = m2 / tot_count
        self.mean = new_mean
        self.var = new_var
        self.count = tot_count

    @property
    def std(self) -> np.ndarray:
        return np.sqrt(self.var)


class StateResetHelper:
    """Helper to save and restore environment simulator states.

    Supports MuJoCo-style ``env.sim.get_state/set_state`` as well as wrappers
    that expose ``get_state`` / ``set_state``. For environments where exact
    state reset is unavailable, it falls back to action replay from a recorded
    initial state.
    """

    def __init__(self, env: gym.Env) -> None:
        self.env = env
        self._initial_state: Optional[Any] = None
        self._initial_obs: Optional[np.ndarray] = None

    def capture_initial(self) -> None:
        """Capture the state returned by a fresh ``reset()``.

        This is useful for deterministic replay-based resets.
        """
        obs = self.env.reset()
        self._initial_obs = obs
        self._initial_state = self.get_state()

    def get_state(self) -> Any:
        """Attempt to extract the current simulator state."""
        # Direct wrapper support
        if hasattr(self.env, "get_state") and callable(getattr(self.env, "get_state")):
            return self.env.get_state()
        # Unwrapped MuJoCo support
        unwrapped = self.env.unwrapped if hasattr(self.env, "unwrapped") else self.env
        if hasattr(unwrapped, "sim") and hasattr(unwrapped.sim, "get_state"):
            return unwrapped.sim.get_state()
        if hasattr(unwrapped, "get_state") and callable(getattr(unwrapped, "get_state")):
            return unwrapped.get_state()
        return None

    def set_state(self, state: Any) -> bool:
        """Attempt to restore the simulator state.

        Returns:
            True if the state was restored successfully, False otherwise.
        """
        if state is None:
            return False
        try:
            if hasattr(self.env, "set_state") and callable(getattr(self.env, "set_state")):
                self.env.set_state(state)
                return True
            unwrapped = self.env.unwrapped if hasattr(self.env, "unwrapped") else self.env
            if hasattr(unwrapped, "sim") and hasattr(unwrapped.sim, "set_state"):
                unwrapped.sim.set_state(state)
                unwrapped.sim.forward()
                return True
            if hasattr(unwrapped, "set_state") and callable(getattr(unwrapped, "set_state")):
                unwrapped.set_state(state)
                return True
        except Exception:
            pass
        return False

    def reset_to_state(self, state: Any) -> np.ndarray:
        """Reset the environment to a given state.

        Falls back to a normal reset if state restoration fails.
        """
        if self.set_state(state):
            # After restoring simulator state, re-observe. For MuJoCo this is
            # typically done by stepping with a zero action or calling reset.
            try:
                obs = self.env.reset()
                # Re-apply state because reset may have changed it.
                self.set_state(state)
                return obs
            except Exception:
                return self.env.reset()
        return self.env.reset()

    def replay_to_state(
        self,
        actions: List[np.ndarray],
        initial_state: Optional[Any] = None,
    ) -> np.ndarray:
        """Replay a sequence of actions from the initial state to reach a target state.

        This is a fallback for environments that do not support direct state save/load.
        """
        if initial_state is not None:
            self.reset_to_state(initial_state)
        else:
            self.env.reset()
        obs = None
        for action in actions:
            obs, _, done, _ = self.env.step(action)
            if done:
                obs = self.env.reset()
        return obs if obs is not None else self.env.reset()


def collect_trajectories(
    env: gym.Env,
    policy: Callable[[np.ndarray], np.ndarray],
    n_trajectories: int = 500,
    max_steps: int = 1000,
    seed: Optional[int] = None,
    deterministic: bool = True,
) -> List[Dict[str, Any]]:
    """Collect trajectories from a policy.

    Args:
        env: Gym environment.
        policy: Callable that maps an observation to an action.
        n_trajectories: Number of trajectories to collect.
        max_steps: Maximum number of steps per trajectory.
        seed: Optional seed.
        deterministic: If True, the policy is called deterministically when
            possible (SB3 policies accept a ``deterministic`` kwarg).

    Returns:
        A list of trajectory dictionaries with keys:
        ``observations``, ``actions``, ``rewards``, ``dones``, ``total_reward``.
    """
    set_seed(seed, env)
    trajectories: List[Dict[str, Any]] = []
    for _ in range(n_trajectories):
        obs = env.reset()
        observations = [obs]
        actions = []
        rewards = []
        dones = []
        total_reward = 0.0
        for _ in range(max_steps):
            try:
                action, _ = policy(obs, deterministic=deterministic)
            except TypeError:
                action = policy(obs)
            actions.append(action)
            step_result = env.step(action)
            if len(step_result) == 5:
                obs, reward, terminated, truncated, info = step_result
                done = terminated or truncated
            else:
                obs, reward, done, info = step_result
            observations.append(obs)
            rewards.append(reward)
            dones.append(done)
            total_reward += reward
            if done:
                break
        trajectories.append(
            {
                "observations": np.array(observations),
                "actions": np.array(actions),
                "rewards": np.array(rewards),
                "dones": np.array(dones),
                "total_reward": total_reward,
            }
        )
    return trajectories


def rollout_policy(
    env: gym.Env,
    policy: Callable[[np.ndarray], np.ndarray],
    max_steps: int = 1000,
    seed: Optional[int] = None,
    deterministic: bool = True,
) -> Tuple[float, int, Dict[str, Any]]:
    """Roll out a single episode and return the total reward and length.

    Returns:
        (total_reward, episode_length, info)
    """
    set_seed(seed, env)
    obs = env.reset()
    total_reward = 0.0
    length = 0
    info = {}
    for _ in range(max_steps):
        try:
            action, _ = policy(obs, deterministic=deterministic)
        except TypeError:
            action = policy(obs)
        step_result = env.step(action)
        if len(step_result) == 5:
            obs, reward, terminated, truncated, info = step_result
            done = terminated or truncated
        else:
            obs, reward, done, info = step_result
        total_reward += reward
        length += 1
        if done:
            break
    return total_reward, length, info


def evaluate_policy(
    env: gym.Env,
    policy: Callable[[np.ndarray], np.ndarray],
    n_episodes: int = 10,
    max_steps: int = 1000,
    seed: Optional[int] = None,
    deterministic: bool = True,
) -> Dict[str, float]:
    """Evaluate a policy over multiple episodes.

    Returns:
        Dictionary with ``mean_reward``, ``std_reward``, ``mean_length``.
    """
    rewards = []
    lengths = []
    for i in range(n_episodes):
        ep_seed = seed + i if seed is not None else None
        total_reward, length, _ = rollout_policy(
            env, policy, max_steps=max_steps, seed=ep_seed, deterministic=deterministic
        )
        rewards.append(total_reward)
        lengths.append(length)
    return {
        "mean_reward": float(np.mean(rewards)),
        "std_reward": float(np.std(rewards)),
        "mean_length": float(np.mean(lengths)),
    }


def load_sb3_policy(path: str, env: Optional[gym.Env] = None):
    """Load a Stable-Baselines3 policy from a checkpoint.

    Args:
        path: Path to the saved model (zip file or directory).
        env: Optional environment used for observation/action space validation.

    Returns:
        Loaded SB3 model.
    """
    from stable_baselines3 import PPO, SAC

    if not os.path.exists(path):
        raise FileNotFoundError(f"Policy checkpoint not found: {path}")

    # Try common SB3 model types
    errors = []
    for ModelClass in (PPO, SAC):
        try:
            model = ModelClass.load(path, env=env)
            return model
        except Exception as e:
            errors.append(str(e))
    raise RuntimeError(f"Failed to load SB3 policy from {path}: {errors}")


def make_policy_callable(model: Any, deterministic: bool = True) -> Callable[[np.ndarray], np.ndarray]:
    """Wrap an SB3 model (or any object with ``predict``) into a simple callable."""

    def policy(obs: np.ndarray) -> np.ndarray:
        action, _ = model.predict(obs, deterministic=deterministic)
        return action

    return policy


def count_parameters(model: nn.Module) -> int:
    """Return the number of trainable parameters in a PyTorch module."""
    return sum(p.numel() for p in model.parameters() if p.requires_grad)


def get_device(device: Union[str, torch.device, None] = "auto") -> torch.device:
    """Resolve a device string to a torch.device."""
    if isinstance(device, torch.device):
        return device
    if device == "auto":
        return torch.device("cuda" if torch.cuda.is_available() else "cpu")
    return torch.device(device)


def save_checkpoint(
    path: str,
    policy_state: Dict[str, Any],
    extra: Optional[Dict[str, Any]] = None,
) -> None:
    """Save a PyTorch checkpoint containing policy state and optional metadata."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    checkpoint = {"policy_state": policy_state}
    if extra is not None:
        checkpoint.update(extra)
    torch.save(checkpoint, path)


def load_checkpoint(path: str, map_location: Optional[str] = None) -> Dict[str, Any]:
    """Load a PyTorch checkpoint."""
    return torch.load(path, map_location=map_location)
